INSERT INTO system.company_setting (id, singleton, company_name_en, company_name_ar, cr_number, vat_id, vat_enabled, vat_percentage, vat_certificate_url, default_currency, currency_decimals, address_en, address_ar, phone, country_code, mobile_number, whatsapp_phone, whatsapp_country_code, whatsapp_mobile_number, email, website, instagram_url, linkedin_url, youtube_url, map_url, bank_name, bank_iban, bank_account_number, bank_swift, time_zone, logo_url, dark_logo_url, full_logo_url, dark_full_logo_url, icon_url, dark_icon_url, stamp_url, signature_url, document_header_url, document_footer_url, payment_terms_days, invoice_prefix, invoice_next_number, receipt_prefix, receipt_next_number, ceo_name_en, ceo_name_ar, ceo_title_en, ceo_title_ar, ceo_quote_en, ceo_quote_ar, tagline_en, tagline_ar, about_text_en, about_text_ar, mission_en, mission_ar, vision_en, vision_ar, terms_en, terms_ar, rules_en, rules_ar, founded_year, city, country, primary_language, business_activity, default_discount_limit_percent, quotations_always_need_approval, theme, setup_completed_at, website_domain, admin_domain, updated_at) VALUES ('c0000000-0000-0000-0000-000000000001', 1, 'Lumina Beauty Atelier W.L.L.', 'لومينا أتيليه للتجميل ذ.م.م', 'CR-161204-1', '200016120400002', true, 10, '/api/files/brand/stamp.png', 'BHD', 3, 'Villa 88, Riffa Views Boulevard, Southern Governorate', 'فيلا 88، بوليفارد رفاع فيوز، المحافظة الجنوبية', '+97317773400', 'BH', '17773400', '+97333773400', 'BH', '33773400', 'concierge@luminaatelier.bh', 'https://luminaatelier.bh', 'https://instagram.com/lumina-atelier', 'https://linkedin.com/company/lumina-atelier', 'https://youtube.com/@lumina-atelier', 'https://maps.google.com/?q=Riffa%2C%20Bahrain', 'Bank of Bahrain and Kuwait (BBK)', 'BH12BBKU00000061204001', '0061204001', 'BBKUBHBM', 'Asia/Bahrain', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/logo-dark.png', '/api/files/brand/logo-light.png', '/api/files/brand/icon-light.png', '/api/files/brand/icon-dark.png', '/api/files/brand/stamp.png', '/api/files/brand/signature.png', '/api/files/media/banners/banner-01.png', '/api/files/media/banners/banner-02.png', 30, 'LMA', 150, 'RCT', 150, 'Dana Al-Sabah', 'دانة الصباح', 'Creative Founder', 'المؤسسة والمديرة الإبداعية', 'Precision delivery from Riffa across the GCC.', 'التميز التشغيلي من Riffa إلى جميع أسواق الخليج.', 'Botanical Skincare Boutique & Luxury Salon', 'بوتيك العناية بالبشرة النباتية وصالون فاخر', 'Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary.', 'أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية.', 'Deliver benchmark beauty services with clear bilingual accountability.', 'تقديم خدمات موثوقة ثنائية اللغة وفق أعلى معايير الجودة والالتزام.', 'To lead Bahrain''s enterprise ecosystem in beauty innovation.', 'أن نكون الشريك المرجعي الأول لقطاع الأعمال في مملكة البحرين والخليج.', 'Invoices are payable within 30 calendar days in BHD. Late balances accrue documented reminders.', 'تستحق الفواتير خلال 30 يوماً بعملة BHD وفق شروط العقد المعتمد.', '10% VAT compliant with Bahrain NBR e-invoicing guidelines; signed approvals logged digitally.', 'تطبق ضريبة القيمة المضافة 10% وفق متطلبات الجهاز الوطني للإيرادات.', 2021, 'Riffa', 'BH', 'ar', 'beauty', 15, false, '{"primary":"#831843","accent":"#D97706","radius":"lg","defaultMode":"light","fonts":{"body":{"kind":"google","family":"Plus Jakarta Sans"},"heading":{"kind":"google","family":"Plus Jakarta Sans"}}}'::jsonb, '2026-01-01T00:00:00Z', 'luminaatelier.bh', 'admin.luminaatelier.bh', now()) ON CONFLICT (id) DO NOTHING;
