INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'lumina-atelier-case-1', 'Riffa Flagship Botanical Spa Sanctuary', 'افتتاح الفرع الرئيسي للسبا النباتي بالرفاع', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Riffa with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Riffa وفق أعلى معايير الجودة والالتزام.', 96, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://luminaatelier.bh/work/lumina-atelier-case-1', 'Riffa, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'lumina-atelier-2026-outlook', 'Lumina Atelier 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — لومينا أتيليه', 'Key operational benchmarks, real metrics, and 2026 guidance from Lumina Atelier in Riffa.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من لومينا أتيليه في Riffa.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary. Focusing on Botanical Hydration Facial (75 min), our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية. من خلال خدمة جلسة ترطيب نباتي للوجه (75 دقيقة) نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary.</p><p>Focusing on <strong>Botanical Hydration Facial (75 min)</strong>, our Riffa specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية.</p><p>من خلال خدمة <strong>جلسة ترطيب نباتي للوجه (75 دقيقة)</strong>، يعمل فريقنا في Riffa على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Lumina Atelier 2026 GCC Market Outlook & Benchmarks | Lumina Atelier', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — لومينا أتيليه | لومينا أتيليه', 'Executive guide by Lumina Atelier covering Botanical Hydration Facial (75 min) benchmarks in Bahrain.', 'دليل تنفيذي من لومينا أتيليه حول معايير جلسة ترطيب نباتي للوجه (75 دقيقة) في البحرين.', 'Insights', '{"beauty","insights","Riffa","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Lumina Atelier initiate a Botanical Hydration Facial (75 min) engagement?', 'كم يستغرق بدء تنفيذ خدمة جلسة ترطيب نباتي للوجه (75 دقيقة) لدى لومينا أتيليه؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Riffa.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Riffa.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'lumina-atelier-case-2', 'Clean Halal-Certified Formulation Line', 'خط مستحضرات نظيفة وحاصلة على شهادة الحلال', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Riffa with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Riffa وفق أعلى معايير الجودة والالتزام.', 96, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://luminaatelier.bh/work/lumina-atelier-case-2', 'Riffa, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'lumina-atelier-service-standards', 'Inside Our Skin SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في جلسة ترطيب نباتي للوجه (75 دقيقة)', 'Key operational benchmarks, real metrics, and 2026 guidance from Lumina Atelier in Riffa.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من لومينا أتيليه في Riffa.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary. Focusing on Signature Gloss & Styling, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية. من خلال خدمة تصفيف وعناية بالشعر نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary.</p><p>Focusing on <strong>Signature Gloss & Styling</strong>, our Riffa specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية.</p><p>من خلال خدمة <strong>تصفيف وعناية بالشعر</strong>، يعمل فريقنا في Riffa على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Skin SLA: Speed, Quality & Auditability | Lumina Atelier', 'معايير اتفاقية مستوى الخدمة والجودة في جلسة ترطيب نباتي للوجه (75 دقيقة) | لومينا أتيليه', 'Executive guide by Lumina Atelier covering Signature Gloss & Styling benchmarks in Bahrain.', 'دليل تنفيذي من لومينا أتيليه حول معايير تصفيف وعناية بالشعر في البحرين.', 'Operations', '{"beauty","operations","Riffa","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-161204-1 and VAT ID 200016120400002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-161204-1 والرقم الضريبي 200016120400002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
