INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-3', 'lumina-atelier-arabic-bilingual-ops', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين', 'Key operational benchmarks, real metrics, and 2026 guidance from Lumina Atelier in Riffa.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من لومينا أتيليه في Riffa.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary. Focusing on Hydra-Cellular Barrier Renewal Facial, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية. من خلال خدمة جلسة تجديد البشرة العميق والترطيب الخلوي نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary.</p><p>Focusing on <strong>Hydra-Cellular Barrier Renewal Facial</strong>, our Riffa specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية.</p><p>من خلال خدمة <strong>جلسة تجديد البشرة العميق والترطيب الخلوي</strong>، يعمل فريقنا في Riffa على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-03.png', 'Why True Arabic-First Workflows Matter in Bahrain Enterprises | Lumina Atelier', 'أهمية تدفقات العمل العربية المتكاملة في مؤسسات البحرين | لومينا أتيليه', 'Executive guide by Lumina Atelier covering Hydra-Cellular Barrier Renewal Facial benchmarks in Bahrain.', 'دليل تنفيذي من لومينا أتيليه حول معايير جلسة تجديد البشرة العميق والترطيب الخلوي في البحرين.', 'Governance', '{"beauty","governance","Riffa","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '18 days', true, now() - interval '18 days', now()) ON CONFLICT (id) DO NOTHING;
