INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"Lumina Beauty Atelier W.L.L.","nameAr":"لومينا أتيليه للتجميل ذ.م.م","shortEn":"Lumina Atelier","shortAr":"لومينا أتيليه","taglineEn":"Botanical Skincare Boutique & Luxury Salon","taglineAr":"بوتيك العناية بالبشرة النباتية وصالون فاخر","aboutEn":"Curated beauty atelier combining bespoke facial rituals, hair artistry, and an online botanical skincare apothecary.","aboutAr":"أتيليه تجميل يجمع بين جلسات العناية بالبشرة المخصصة ومتجر إلكتروني لمنتجات العناية النباتية."},"hero":{"titleEn":"Lumina Atelier — Botanical Skincare Boutique & Luxury Salon","titleAr":"لومينا أتيليه — بوتيك العناية بالبشرة النباتية وصالون فاخر","ctaLabelEn":"Explore Lumina Atelier","ctaLabelAr":"استكشف لومينا أتيليه"},"banners":[{"id":"hero-1","title_en":"Lumina Atelier: Botanical Hydration Facial (75 min)","title_ar":"لومينا أتيليه: جلسة ترطيب نباتي للوجه (75 دقيقة)","subtitle_en":"Botanical Skincare Boutique & Luxury Salon","subtitle_ar":"بوتيك العناية بالبشرة النباتية وصالون فاخر","media_type":"image","media_url":"/api/files/media/banners/banner-01.png","poster_url":"/api/files/media/banners/banner-01.png","display_order":1,"is_active":true,"cta_label_en":"Request Proposal","cta_label_ar":"اطلب عرض سعر","cta_link":"/contact"},{"id":"hero-2","title_en":"Lumina Atelier: Signature Gloss & Styling","title_ar":"لومينا أتيليه: تصفيف وعناية بالشعر","subtitle_en":"Botanical Skincare Boutique & Luxury Salon","subtitle_ar":"بوتيك العناية بالبشرة النباتية وصالون فاخر","media_type":"image","media_url":"/api/files/media/banners/banner-02.png","poster_url":"/api/files/media/banners/banner-02.png","display_order":2,"is_active":true,"cta_label_en":"Explore Our Work","cta_label_ar":"استعرض أعمالنا","cta_link":"/work"},{"id":"hero-3","title_en":"Lumina Atelier: Hydra-Cellular Barrier Renewal Facial","title_ar":"لومينا أتيليه: جلسة تجديد البشرة العميق والترطيب الخلوي","subti